settings.custom_css:
.connector::before {
   content: "";
    position: absolute;
    top: 8%;
    left: 2%;
    height: 1px;
    width: 74%;
    background: #7EB13E;
}

@media screen and (max-width: 1440px) {
    .connector::before{
        width: 70%;
    }
}

@media screen and (max-width: 768px) {
    
     .connector::before{
        width: 0%;
    }
}

@media screen and (min-width: 1441px) and (max-width: 1650px) {
    
    .process-box-heding h3{
        font-size: 26px !important;
        line-height: 38px !important;
    }

}

